pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Calculate the fine-grained residual fitting bonus
    let cpu_fit_bonus = if job_cpu <= node_residual_cpu {
        0.5 * ((node_residual_cpu - job_cpu) as f64 / mean_cpu_residual).powi(2)
    } else {
        0.0
    };
    let ram_fit_bonus = if job_ram <= node_residual_ram {
        0.5 * ((node_residual_ram - job_ram) as f64 / mean_ram_residual).powi(2)
    } else {
        0.0
    };

    // Calculate the lookahead packing bonus
    let next_job_total_cpu = next_job_cpu + job_cpu;
    let next_job_total_ram = next_job_ram + job_ram;
    let lookahead_bonus = if next_job_total_cpu <= node_residual_cpu && next_job_total_ram <= node_residual_ram {
        2.0 // Increased bonus for perfect fit
    } else if (next_job_total_cpu > node_residual_cpu || next_job_total_ram > node_residual_ram) && (next_job_cpu <= node_residual_cpu || next_job_ram <= node_residual_ram) {
        1.5 // Bonus for partial fit
    } else {
        -0.5; // Penalty if the next job does not fit well
    };

    let horizon_factor = (step_index as f64 / total_jobs as f64).powi(3); // Increased power to penalize mismatches more heavily over time
    let score = cpu_norm + ram_norm - imbalance_penalty * 2.0 - horizon_factor * imbalance_penalty + lookahead_bonus + cpu_fit_bonus + ram_fit_bonus;

    score
}

pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;

    // Reward for fitting the job and its next job
    let mut score = 1.0 - (cpu_norm + ram_norm) / 2.0; // Balance residual usage

    if next_job_cpu <= node_residual_cpu && next_job_ram <= node_residual_ram {
        // Penalize stranding the upcoming job
        score += 0.5;
    } else {
        // Reward for pairing complementary jobs
        score -= 0.5;
    }

    // Adjust score based on step index and total jobs to account for dynamic horizon
    if step_index == 0 && active_nodes_count < total_jobs / 2 {
        score += 0.3;
    } else if step_index > total_jobs / 4 && node_residual_cpu + next_job_cpu <= node_capacity_cpu && node_residual_ram + next_job_ram <= node_capacity_ram {
        score -= 0.3;
    }

    score
}

pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    let mut score = 2.0 * cpu_norm + 2.0 * ram_norm - imbalance_penalty * 3.0; // Increased penalty and reward for imbalances

    if job_cpu > job_ram {
        // CPU-heavy job
        score -= (node_residual_cpu as f64 / mean_cpu_residual).powi(3); // Higher power to penalize mismatches more heavily
    } else {
        // RAM-heavy job
        score -= (node_residual_ram as f64 / mean_ram_residual).powi(3);
    }

    let perfect_fit_bonus = if next_job_cpu + job_cpu <= node_residual_cpu && next_job_ram + job_ram <= node_residual_ram {
        1.5; // Increased bonus for perfect fit
    } else {
        0.0;
    };

    let partial_fit_bonus = if (next_job_cpu + job_cpu > node_residual_cpu || next_job_ram + job_ram > node_residual_ram) && (next_job_cpu <= node_residual_cpu || next_job_ram <= node_residual_ram) {
        0.75; // Bonus for partial fit
    } else {
        0.0;
    };

    let lookahead_bonus = if next_job_cpu + job_cpu <= node_residual_cpu && next_job_ram + job_ram <= node_residual_ram {
        1.25; // Higher bonus if the next job fits well
    } else {
        -0.5; // Penalty if the next job does not fit well
    };

    let horizon_factor = (step_index as f64 / total_jobs as f64).powi(3); // Increased power to penalize mismatches more heavily over time
    score -= horizon_factor * imbalance_penalty;
    score += perfect_fit_bonus + partial_fit_bonus + lookahead_bonus;

    score
}

